-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 3
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 3 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 03', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 03 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-03.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Cite quatro itens que devem ser conferidos antes de instalar.', 0.2, 'Quatro entre: sistema operacional **64 bits** suportado; **espaço em disco**; **porta 5432 livre**; **permissão de administrador**; **versão** definida pela equipe; memória.', 'Nota cheia (0,2): quatro itens corretos. Metade (0,1): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 1, 2, 'Explique por que todas as máquinas devem ficar com a mesma versão principal do PostgreSQL.', 0.4, 'Para que o banco **se comporte igual** em todas as máquinas: comandos, recursos e scripts funcionam do mesmo jeito, evitando erros que só aparecem numa versão.', 'Palavras-chave: mesmo comportamento; scripts/comandos iguais; evita erros entre máquinas. Nota cheia (0,4): motivo com consequência. Metade (0,2): "para ficar padronizado" sem consequência. Zero (0): sem relação.'),
      (v_atividade, 1, 3, 'Explique o que pode acontecer se a porta 5432 já estiver em uso e como evitar o problema.', 0.4, 'Se outro PostgreSQL já usa a **5432**, o novo não consegue usar a mesma porta (o instalador avisa ou o serviço não sobe) e as conexões podem ir para o servidor errado. Evita-se **conferindo antes** se há instalação anterior e, se houver, **removendo-a** ou escolhendo **outra porta livre** (e registrando-a).', 'Nota cheia (0,4): consequência + forma de evitar. Metade (0,2): só um dos dois. Zero (0): sem relação com porta.'),
      (v_atividade, 2, 1, 'Diga a função do componente Server.', 0.2, 'O **Server** é o próprio **SGBD**: roda como **serviço** e **guarda os dados**, atendendo às conexões.', 'Nota cheia (0,2): SGBD/serviço que guarda os dados. Metade (0,1): "o principal" sem explicar. Zero (0): confunde com cliente gráfico.'),
      (v_atividade, 2, 2, 'Explique a diferença entre o psql (Command Line Tools) e o pgAdmin.', 0.4, 'O **psql** é um cliente de **terminal** (comandos digitados); o **pgAdmin** é um cliente **gráfico** (janelas e menus). Os dois **conectam ao mesmo servidor** e executam SQL.', 'Nota cheia (0,4): terminal × gráfico + mesmo servidor. Metade (0,2): só a diferença terminal × gráfico. Zero (0): diz que um deles guarda os dados.'),
      (v_atividade, 2, 3, 'Diga se o Stack Builder é obrigatório e explique o que é a pasta de dados escolhida na instalação.', 0.4, 'O Stack Builder é **opcional** (instala extensões extras). A **pasta de dados** é onde o PostgreSQL grava **os arquivos do banco** (nível físico), importante para espaço em disco e backup.', 'Nota cheia (0,4): opcional + definição da pasta de dados. Metade (0,2): só um dos dois. Zero (0): diz que é obrigatório e não explica a pasta.'),
      (v_atividade, 3, 1, 'Diga o que é o usuário postgres criado na instalação.', 0.2, 'É o **superusuário** do PostgreSQL, com **todos os poderes** sobre o servidor (criar bancos, usuários, apagar dados).', 'Nota cheia (0,2): superusuário/administrador com todos os poderes. Metade (0,1): "usuário padrão" sem citar os poderes. Zero (0): confunde com usuário do sistema web.'),
      (v_atividade, 3, 2, 'Explique por que a senha "123" e a senha no código do sistema são riscos.', 0.4, '"123" é **fácil de adivinhar**; no **código do sistema**, a senha fica visível para quem tem acesso ao código ou ao repositório. Com a senha do superusuário, alguém pode **ler, alterar ou apagar todo o banco**.', 'Nota cheia (0,4): os dois riscos + consequência. Metade (0,2): só um risco. Zero (0): diz que não há risco.'),
      (v_atividade, 3, 3, 'Explique onde guardar a senha e com qual usuário a aplicação deve se conectar.', 0.4, 'Guardar num **gerenciador de senhas/cofre** de acesso restrito. A aplicação deve se conectar com um **usuário próprio**, com **apenas as permissões necessárias**, e nunca com o postgres.', 'Nota cheia (0,4): local seguro + usuário próprio com permissões mínimas. Metade (0,2): só um dos dois. Zero (0): mantém a senha no código ou usa o postgres na aplicação.'),
      (v_atividade, 4, 1, 'Diga qual é a porta padrão do PostgreSQL.', 0.2, '**5432.**', 'Nota cheia (0,2): 5432. Zero (0): outra porta.'),
      (v_atividade, 4, 2, 'Explique o que é o locale escolhido na instalação e o que ele influencia.', 0.4, 'O **locale** é o **idioma e a região** do banco (ex.: Portuguese, Brazil); influencia a **ordenação de textos**, comparação de letras e **formatos** de data e números.', 'Nota cheia (0,4): definição + o que influencia. Metade (0,2): só a definição. Zero (0): confunde com porta ou senha.'),
      (v_atividade, 4, 3, 'Explique a causa provável dos acentos errados e qual codificação deve ser usada.', 0.4, 'Causa provável: **codificação** do banco diferente de **UTF8** (ou do cliente diferente da do banco). Deve-se usar **UTF8**, que guarda corretamente acentos e caracteres especiais.', 'Palavras-chave: codificação; UTF8. Nota cheia (0,4): causa + UTF8. Metade (0,2): só UTF8 sem explicar a causa. Zero (0): culpa a porta ou o teclado.'),
      (v_atividade, 5, 1, 'Escreva o comando que instala o PostgreSQL no Ubuntu.', 0.2, '**sudo apt install postgresql postgresql-contrib** (precedido de sudo apt update).', 'Nota cheia (0,2): comando apt install postgresql. Metade (0,1): comando incompleto mas com apt e postgresql. Zero (0): comando de outro sistema.'),
      (v_atividade, 5, 2, 'Escreva o comando que mostra se o serviço está ativo e o que faz iniciar o serviço junto com o sistema.', 0.4, '**sudo systemctl status postgresql** mostra se está ativo; **sudo systemctl enable postgresql** faz iniciar junto com o sistema.', 'Nota cheia (0,4): os dois comandos. Metade (0,2): um comando. Zero (0): nenhum correto.'),
      (v_atividade, 5, 3, 'Explique como entrar no psql como o usuário postgres logo após a instalação e por que esse usuário existe no sistema.', 0.4, '**sudo -u postgres psql**: executa o psql como o **usuário postgres do sistema**, que a instalação cria para **rodar o serviço** e fazer o primeiro acesso local de administração.', 'Nota cheia (0,4): comando + motivo do usuário. Metade (0,2): só o comando ou só o motivo. Zero (0): comando errado sem explicação.'),
      (v_atividade, 6, 1, 'Escreva o comando de terminal que conecta ao servidor local com o usuário postgres na porta 5432.', 0.2, '**psql -U postgres -h localhost -p 5432**', 'Nota cheia (0,2): comando com usuário, servidor e porta. Metade (0,1): falta um parâmetro. Zero (0): comando sem relação.'),
      (v_atividade, 6, 2, 'Explique o que mostram os comandos SELECT version(); e \l dentro do psql.', 0.4, '**SELECT version();** mostra a **versão do servidor** conectado; **\l** **lista os bancos** do servidor.', 'Nota cheia (0,4): os dois corretos. Metade (0,2): um correto. Zero (0): nenhum.'),
      (v_atividade, 6, 3, 'Explique como registrar o servidor no pgAdmin e quais bancos devem aparecer numa instalação nova.', 0.4, 'No pgAdmin: **Servers → Register → Server**, informar **localhost, porta 5432, usuário postgres e senha**. Numa instalação nova aparecem os bancos **postgres, template0 e template1**.', 'Nota cheia (0,4): dados do registro + bancos iniciais. Metade (0,2): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 7, 1, 'Explique o que significa o PostgreSQL rodar como serviço.', 0.2, 'O servidor fica rodando **em segundo plano**, sem janela, **esperando conexões**; se o serviço para, ninguém conecta.', 'Nota cheia (0,2): segundo plano + esperando conexões. Metade (0,1): só uma das ideias. Zero (0): confunde com o pgAdmin.'),
      (v_atividade, 7, 2, 'Explique como conferir e iniciar o serviço no Windows.', 0.4, 'Abrir o aplicativo **Serviços** do Windows, localizar **postgresql-x64-NN**, conferir o **status** e clicar em **Iniciar** se estiver parado; depois testar a conexão de novo.', 'Nota cheia (0,4): onde conferir + iniciar + testar. Metade (0,2): só "reiniciar o computador" ou só "abrir serviços". Zero (0): reinstalar tudo como primeira solução.'),
      (v_atividade, 7, 3, 'Explique como evitar que o problema se repita depois de reiniciar, no Windows ou no Linux.', 0.4, 'Deixar o serviço com início **automático**: no Windows, tipo de inicialização **Automático** nas propriedades do serviço; no Linux, **sudo systemctl enable postgresql**.', 'Nota cheia (0,4): início automático em pelo menos um sistema, explicado. Metade (0,2): ideia de "iniciar sempre" sem dizer como. Zero (0): sem relação.'),
      (v_atividade, 8, 1, 'Diga a causa provável de cada um dos dois erros.', 0.2, '(1) **Serviço parado ou porta errada**; (2) **senha errada** para o usuário postgres.', 'Nota cheia (0,2): as duas causas. Metade (0,1): uma. Zero (0): nenhuma.'),
      (v_atividade, 8, 2, 'Explique os passos para resolver o erro 1.', 0.4, 'Conferir se o **serviço está ativo** (Serviços no Windows ou systemctl status no Linux) e iniciá-lo; conferir a **porta** usada na instalação (5432 ou outra registrada) e usá-la na conexão; se o banco estiver em outra máquina, conferir o **firewall**.', 'Nota cheia (0,4): serviço + porta (firewall é bônus). Metade (0,2): só um passo. Zero (0): passos sem relação.'),
      (v_atividade, 8, 3, 'Explique os passos para resolver o erro 2 sem expor a senha.', 0.4, 'Conferir se o **usuário e a senha** digitados estão certos (sem erro de digitação, Caps Lock); se a senha foi perdida, pedir ao **DBA/responsável** que a **redefina** e guardá-la no **cofre de senhas**, sem enviá-la por mensagem aberta nem colocá-la no código.', 'Nota cheia (0,4): conferir + redefinir com o responsável + não expor. Metade (0,2): só conferir ou só redefinir. Zero (0): sugere publicar a senha ou desligar a autenticação.'),
      (v_atividade, 9, 1, 'Diga a causa provável de cada caso.', 0.2, 'psql não reconhecido: a **pasta bin do PostgreSQL não está no PATH**. Porta em uso: **já existe outro PostgreSQL** (ou programa) usando a 5432.', 'Nota cheia (0,2): as duas causas. Metade (0,1): uma. Zero (0): nenhuma.'),
      (v_atividade, 9, 2, 'Explique duas formas de resolver o caso do psql não reconhecido.', 0.4, '(1) usar o atalho **"SQL Shell (psql)"** instalado junto; (2) **acrescentar a pasta bin** do PostgreSQL ao **PATH** do Windows (ou chamar o psql pelo caminho completo).', 'Nota cheia (0,4): duas formas. Metade (0,2): uma forma. Zero (0): reinstalar o Windows.'),
      (v_atividade, 9, 3, 'Explique duas formas de resolver o caso da porta em uso e o cuidado com a conexão depois.', 0.4, '(1) **remover a instalação antiga** que ocupa a porta (se não for usada); (2) **usar outra porta livre** (ex.: 5433). Cuidado: depois, **todas as conexões** (psql, pgAdmin, aplicação) devem usar a porta nova, registrada no roteiro.', 'Nota cheia (0,4): duas formas + cuidado com a conexão. Metade (0,2): uma forma ou duas sem o cuidado. Zero (0): instalar por cima na mesma porta.'),
      (v_atividade, 10, 1, 'Liste o que deve ser registrado no roteiro de instalação.', 0.2, '**Versão**, **porta**, **pasta de dados**, **locale/codificação**, **data**, **quem instalou** (e problemas encontrados com a solução).', 'Nota cheia (0,2): quatro ou mais itens. Metade (0,1): dois ou três. Zero (0): inclui a senha em texto aberto como item.'),
      (v_atividade, 10, 2, 'Explique a ordem correta da preparação do ambiente, do checklist ao teste final.', 0.4, '(1) conferir **requisitos** (checklist); (2) **instalar** (componentes, senha, porta, locale); (3) conferir o **serviço** ativo; (4) **testar a conexão** (psql e pgAdmin, SELECT version()).', 'Nota cheia (0,4): as quatro etapas na ordem. Metade (0,2): etapas certas fora de ordem ou faltando uma. Zero (0): começa criando tabelas.'),
      (v_atividade, 10, 3, 'Explique duas boas práticas de segurança da instalação e por que são importantes.', 0.4, 'Duas entre: **senha forte** do postgres guardada em **cofre**; aplicação com **usuário próprio** de permissões mínimas; **baixar só do site oficial**; **instalar só os componentes necessários**; liberar a porta **só para quem precisa** no firewall. Importantes porque **reduzem o risco** de acesso indevido aos dados.', 'Nota cheia (0,4): duas práticas + importância. Metade (0,2): uma prática ou duas sem importância. Zero (0): práticas inseguras.');
end $$;
